CREATE FUNCTION pg_temp.assert03b(ok boolean, label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF;
RAISE NOTICE 'PASS: %',label; END; $$;
