SELECT pg_temp.assert03b((SELECT count(*)=46 FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'),'46 tables');
SELECT pg_temp.assert03b((SELECT count(*)=291 FROM pg_policies WHERE schemaname='public'),'291 policies');
SELECT pg_temp.assert03b((SELECT count(*)=126 FROM pg_policies WHERE schemaname='public' AND permissive='RESTRICTIVE'),'126 restrictive guards');
SELECT pg_temp.assert03b(NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND NOT c.relrowsecurity),'RLS enabled');
SELECT pg_temp.assert03b((SELECT count(*)=7 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f'),'six helpers plus trigger function');
SELECT pg_temp.assert03b((SELECT NOT prosecdef AND proconfig=ARRAY['search_path=""']::text[] FROM pg_proc WHERE oid='public.security03b_preserve_tenant()'::regprocedure),'tenant trigger is invoker with empty search_path');
SELECT pg_temp.assert03b(NOT has_function_privilege('anon','public.security03b_preserve_tenant()','EXECUTE') AND NOT has_function_privilege('authenticated','public.security03b_preserve_tenant()','EXECUTE'),'trigger has no exposed RPC EXECUTE');
